mutations.before:
export function holdsExpiringUrls(result: RunResult): boolean {
  return (result.assets ?? []).some((a) =>
    ASSET_URL_FIELDS.some((f) => {
      const u = usableUrl(a[f]);
      return u !== undefined && !u.startsWith("/");
    }),
  );
}

mutations.after:
export function holdsExpiringUrls(result: RunResult): boolean {
  return (result.assets ?? []).some(() => true);
}

